import{e as t,ab as a,a1 as o,m as i,r as n,p as l}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [Sept]","description":"September 2024 updates","frontmatter":{"title":"Monthly Updates [Sept]","description":"September 2024 updates","date":"2024-09-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/sept-2024.md","filePath":"posts/sept-2024.md"}'),s={name:"posts/sept-2024.md"};function h(d,e,p,f,m,g){const r=a("Post");return o(),i("div",null,[n(r,{authors:"nbats"}),e[0]||(e[0]=l('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Made <a href="https://i.ibb.co/4ThbdyN/image.png" target="_blank" rel="noreferrer">multiple updates</a> to our site and feedback system. All pages are now <a href="https://fmhy.net/" target="_blank" rel="noreferrer">visible</a> on the front page, feedback can now be <a href="https://i.ibb.co/k8p2rcF/image.png" target="_blank" rel="noreferrer">sent from any section</a>, and <a href="https://i.ibb.co/tBMwXXy/image.png" target="_blank" rel="noreferrer">site icons</a> have been added for Discord, Telegram, Reddit, Git, etc.</p></li><li><p>Created a <a href="https://github.com/fmhy/bookmarks" target="_blank" rel="noreferrer">method</a> to add all of FMHY to your bookmarks.</p></li><li><p>Added subsections to Minecraft Tools: <a href="https://fmhy.net/gaming-tools#hosting-tools" target="_blank" rel="noreferrer">Hosting</a>, <a href="https://fmhy.net/gaming-tools#launchers" target="_blank" rel="noreferrer">Launchers</a>, <a href="https://fmhy.net/gaming-tools#mods-data-packs" target="_blank" rel="noreferrer">Data Packs</a>, <a href="https://fmhy.net/gaming-tools#maps-world-tools" target="_blank" rel="noreferrer">Map Tools</a>, <a href="https://fmhy.net/gaming-tools#technical-tools" target="_blank" rel="noreferrer">Technical Tools</a>, <a href="https://fmhy.net/gaming-tools#customization" target="_blank" rel="noreferrer">Customization</a>, and <a href="https://fmhy.net/gaming-tools#_3d-tools" target="_blank" rel="noreferrer">3D Tools</a>.</p></li><li><p>Added <a href="https://fmhy.net/ai#chatgpt-tools" target="_blank" rel="noreferrer">ChatGPT Tools</a>, <a href="https://fmhy.net/ai#ai-benchmarks" target="_blank" rel="noreferrer">AI Benchmarks</a>, and <a href="https://fmhy.net/ai#ai-search-engines" target="_blank" rel="noreferrer">AI Search Engine</a> sections to AI.</p></li><li><p>Added <a href="https://fmhy.net/mobile#youtube-music-clients" target="_blank" rel="noreferrer">YouTube Music</a> and <a href="https://fmhy.net/mobile#ios-youtube-apps" target="_blank" rel="noreferrer">YouTube App</a> (iOS) sections to Mobile.</p></li><li><p>Added <a href="https://fmhy.net/developer-tools#coding-tools" target="_blank" rel="noreferrer">Coding Tools</a> and <a href="https://fmhy.net/developer-tools#android-code-editors" target="_blank" rel="noreferrer">Android Code Editor</a> sections to Code Editors.</p></li><li><p>Added a <a href="https://fmhy.net/gaming#geoguessr-games" target="_blank" rel="noreferrer">Geoguessr</a> section to Browser Games.</p></li><li><p>Added a <a href="https://fmhy.net/file-tools#cloud-managers" target="_blank" rel="noreferrer">Cloud Managers</a> section to File Tools.</p></li><li><p>Added a <a href="https://fmhy.net/educational#jee-neet" target="_blank" rel="noreferrer">JEE / NEET</a> section in Edu Tools.</p></li><li><p>Added a <a href="https://fmhy.net/video#streaming-apis" target="_blank" rel="noreferrer">Streaming APIs</a> section to Streaming.</p></li><li><p>Split Audiobooks into <a href="https://fmhy.net/reading#downloading" target="_blank" rel="noreferrer">Downloading</a> and <a href="https://fmhy.net/reading#streaming" target="_blank" rel="noreferrer">Streaming</a>.</p></li><li><p>Made the FMHY site logo easier to switch (click it 5 times).</p></li><li><p>Our filterlist has been moved to <a href="https://fmhy.github.io/FMHYFilterlist/site/index.html" target="_blank" rel="noreferrer">here</a>, and our markdown page to <a href="https://api.fmhy.net/single-page" target="_blank" rel="noreferrer">here</a>.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="https://fmhy.net/reading#ebooks" target="_blank" rel="noreferrer">Bookracy</a> in Ebook Sites. Promising book site with a solid UI and community.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#foss-apks" target="_blank" rel="noreferrer">Droid-ify</a> in FOSS APKs. Open-source F-Droid client some like more than the official.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#adblocking" target="_blank" rel="noreferrer">Disblock Origin</a> in Adblocking. Removes Nitro / Boost ads from Discord.</p></li><li><p>Starred <a href="https://fmhy.net/storage#tab-managers" target="_blank" rel="noreferrer">Sidebery</a> in Tab Managers. Useful open-source tab manager / bookmark manager.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">FastFLUX</a> in AI Image Gen. Good quality and currently unlimited.</p></li><li><p>Starred <a href="https://fmhy.net/ai#ai-search-engines" target="_blank" rel="noreferrer">You</a> in AI Search Engines. Fast, free, unlimited AI search.</p></li><li><p>Starred <a href="https://fmhy.net/reading#fanfiction-stories" target="_blank" rel="noreferrer">Archive of Our Own</a> in Fanfiction Sites. Popular and extensive archive of fanfiction.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#telegram-clients" target="_blank" rel="noreferrer">Materialgram</a> and <a href="https://fmhy.net/mobile#social-media-apps" target="_blank" rel="noreferrer">AyuGram</a> (Android) in Telegram Clients. Simple, ad-free, feature-rich clients.</p></li><li><p>Starred <a href="https://fmhy.net/storage#royalty-free-music" target="_blank" rel="noreferrer">NCS</a> in Royalty Free Music. Popular library for free music.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-internet" target="_blank" rel="noreferrer">K-9 Mail</a> in Android Internet. Open-source mobile mail client.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#optimization-tools" target="_blank" rel="noreferrer">Lossless Scaling</a> in Game Optimization. Powerful upscaling with frame generation for all GPUs.</p></li><li><p>Starred <a href="https://fmhy.net/system-tools#mouse-keyboard" target="_blank" rel="noreferrer">Hotkey Cheatsheet</a> in Keyboard Tools. Keyboard hotkeys for lots of different apps.</p></li><li><p>Starred <a href="https://fmhy.net/video#stremio-tools" target="_blank" rel="noreferrer">Viren070&#39;s Guides</a> in Stremio Tools. Helpful guides to use Stremio.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Said goodbye to both Fmovies and Aniwave.</p></li><li><p>Removed SusFlix as it&#39;s been down for over a week.</p></li><li><p>Removed Lantern as its limit is low (250mb daily) and it&#39;s closed-source.</p></li><li><p>Removed Lexica as they&#39;re removing the free tier.</p></li><li><p>Unstarred APKPure due to their poor privacy policy and low-quality apps.</p></li><li><p>Unstarred ROMhacking as they&#39;re going <a href="https://www.romhacking.net/forum/index.php?topic=39405" target="_blank" rel="noreferrer">archive-only</a>.</p></li><li><p>Unstarred Morphic as they will <a href="https://i.ibb.co/sRVyVKk/image.png" target="_blank" rel="noreferrer">no longer</a> be using paid models for searching.</p></li><li><p>Unstarred sdk.vercel as it requires an account for the better models.</p></li></ul>',9))])}const u=t(s,[["render",h]]);export{b as __pageData,u as default};
